	 "badges$badge.boss_challenge_1.desc": "Derrote o chefe dos esgotos sem deixá-lo usar seu ataque carregado ou se curar na água",
	 "badges$badge.boss_challenge_1.title": "Vitória impecável",
	 "badges$badge.boss_challenge_2.desc": "Derrote o chefe da prisão sem ser atingido por nenhuma armadilha ou truque",
	 "badges$badge.boss_challenge_2.title": "Peguei você!",
	 "badges$badge.boss_challenge_3.desc": "Derrote o chefe das cavernas sem ser atacado ou atingido enquanto ele estiver sobrecarregado",
	 "badges$badge.boss_challenge_3.title": "Estrategista",
	 "badges$badge.boss_challenge_4.desc": "Derrote o chefe da cidade sem atacá-lo diretamente com armas, anéis ou varinhas",
	 "badges$badge.boss_challenge_4.title": "Sem Armas em Sua Presença",
	 "badges$badge.boss_challenge_5.desc": "Derrote o chefe final com todas as forjas demoníacas vivas e com o desafio do chefes mais durões ativado",
	 "badges$badge.boss_slain_1.desc": "Derrote o chefe no final dos esgotos",
	 "badges$badge.boss_slain_1.title": "Zelador de Slime",
